// This service currently simulates NDVI data.
// FUTURE INTEGRATION: Replace these functions with calls to Sentinel Hub or Agromonitoring APIs.

export interface NdviPoint {
    date: string;
    ndvi: number;
    ndre: number | null;
    ndmi: number | null;
    value?: number; // Legacy alias for backward compatibility
}

export const generateMockNdviHistory = (plantingDate: string, cropType: string): NdviPoint[] => {
    const history: NdviPoint[] = [];
    const start = new Date(plantingDate);
    const today = new Date();

    // Create a curve that simulates crop growth
    // 0.2 (soil) -> 0.8 (peak biomass) -> 0.4 (harvest/senescence)

    let currentDate = new Date(start);
    let daysSincePlanting = 0;

    while (currentDate <= today) {
        // Only add data points every ~5 days (Sentinel-2 revisit time)
        if (daysSincePlanting % 5 === 0) {
            // Simple growth curve simulation (Logistic function shape)
            const growthRate = 0.05;
            const peakDay = 90; // Approx 3 months to peak

            // Base calculation
            let val = 0.2 + (0.7 / (1 + Math.exp(-growthRate * (daysSincePlanting - peakDay))));

            // Add some "noise" to simulate real world clouds/variations
            val += (Math.random() * 0.1 - 0.05);

            // Clamp values
            const ndvi = parseFloat(Math.max(0.1, Math.min(0.95, val)).toFixed(3));

            // Simulate other indices correlated with NDVI but slightly different
            const ndre = parseFloat(Math.max(0.1, Math.min(0.8, ndvi * 0.85 + 0.05)).toFixed(3));
            const ndmi = parseFloat(Math.max(-0.2, Math.min(0.6, ndvi * 0.6)).toFixed(3));

            history.push({
                date: currentDate.toISOString().split('T')[0],
                ndvi: ndvi,
                ndre: ndre,
                ndmi: ndmi,
                value: ndvi // Legacy
            });
        }

        currentDate.setDate(currentDate.getDate() + 1);
        daysSincePlanting++;
    }

    return history;
};

// Returns a color based on NDVI value
export const getNdviColor = (value: number): string => {
    if (value < 0.2) return '#a1662f'; // Bare soil (Brown)
    if (value < 0.4) return '#eab308'; // Sparse/Stressed (Yellow)
    if (value < 0.6) return '#84cc16'; // Moderate (Light Green)
    if (value < 0.8) return '#22c55e'; // Dense (Green)
    return '#14532d'; // Very Dense (Dark Green)
};

export const DEFAULT_BACKEND_URL = 'https://ascitic-lyda-rhotic.ngrok-free.dev';

export const getBackendUrl = () => {
    // Ensure no trailing slash
    let url = localStorage.getItem('gee_backend_url') || DEFAULT_BACKEND_URL;
    if (url.endsWith('/')) {
        url = url.slice(0, -1);
    }
    return url;
};

const isOfflineMode = () => {
    return localStorage.getItem('gee_simulation_mode') === 'true';
};

// Helper: Convert {lat, lng} array to [lng, lat] array (GeoJSON Ring)
// Ensures the ring is closed (first point == last point)
const toLngLatRing = (coords: { lat: number, lng: number }[]) => {
    const arr = coords.map(p => [p.lng, p.lat]);
    if (arr.length > 0) {
        const first = arr[0];
        const last = arr[arr.length - 1];
        // Check if closed, if not push first point to end
        if (first[0] !== last[0] || first[1] !== last[1]) {
            arr.push(first);
        }
    }
    return arr;
};

// Formats the frontend boundary object into a standard GeoJSON Polygon geometry
const formatPolygonForBackend = (boundary: any) => {
    let coordinates: number[][][] = [];

    if (Array.isArray(boundary) && boundary.length > 0) {
        // Case 1: Simple polygon (Array of objects {lat, lng})
        if ('lat' in boundary[0]) {
             coordinates = [toLngLatRing(boundary)];
        } 
        // Case 2: Polygon with holes or MultiPolygon structure (Array of Arrays)
        else if (Array.isArray(boundary[0])) {
             coordinates = boundary.map((ring: any) => toLngLatRing(ring));
        }
    }

    // Fallback to avoid sending invalid JSON if boundary is empty
    if (coordinates.length === 0) {
        coordinates = [[[0,0], [0,0], [0,0], [0,0]]];
    }

    return {
        type: "Polygon",
        coordinates: coordinates
    };
};

// ----------------------------------------------------------------------
// 1. Get Tile URL (Map Layer)
// ----------------------------------------------------------------------
export const fetchGeeLayer = async (
    layer: string,
    boundary: any,
    backendUrl: string
): Promise<{ tile_url: string; stats?: { min: number; max: number } } | null> => {
    if (isOfflineMode()) {
        console.log("Offline Mode: Skipping GEE layer fetch.");
        return null;
    }

    try {
        console.log(`Fetching layer '${layer}' from ${backendUrl}...`);
        const polygon = formatPolygonForBackend(boundary);

        const endpoint = `${backendUrl}/api/get-layer`;

        const response = await fetch(endpoint, {
            method: 'POST',
            headers: { 
                'Content-Type': 'application/json',
                'ngrok-skip-browser-warning': 'true' // Critical: Bypasses ngrok free tier warning page
            },
            body: JSON.stringify({ polygon, layer })
        });

        if (!response.ok) {
            const errText = await response.text();
            throw new Error(`Server ${response.status}: ${errText}`);
        }

        const data = await response.json();
        return data; // Returns { tile_url, stats: {min, max} }

    } catch (error: any) {
        console.error("GEE Layer Fetch Failed:", error);
        if (error.message.includes('Failed to fetch')) {
            throw new Error(`Connection refused to ${backendUrl}. Ensure server is running.`);
        }
        throw error;
    }
};

// ----------------------------------------------------------------------
// 2. Get Statistics (Job Queue + Polling)
// ----------------------------------------------------------------------
export interface GeeTimeSeriesPoint {
    date: string;
    value: number; // legacy alias
    ndvi: number;
    ndre: number | null;
    ndmi: number | null;
}

export const fetchGeeTimeSeries = async (
    boundary: any,
    startDate: string,
    endDate: string,
    backendUrl: string
): Promise<GeeTimeSeriesPoint[] | null> => {
    if (isOfflineMode()) {
        console.log("Offline Mode: Skipping fetch.");
        return null;
    }

    try {
        console.log(`Starting stats job on ${backendUrl} (${startDate} to ${endDate})...`);
        const polygon = formatPolygonForBackend(boundary);
        const endpoint = `${backendUrl}/api/get-stats`;

        // Step 1: Submit Job
        let enqueueRes;
        try {
            enqueueRes = await fetch(endpoint, {
                method: 'POST',
                headers: { 
                    'Content-Type': 'application/json',
                    'ngrok-skip-browser-warning': 'true' // Critical: Bypasses ngrok free tier warning page
                },
                body: JSON.stringify({ polygon, startDate, endDate })
            });
        } catch (netErr: any) {
            console.error("Network Error Details:", netErr);
            throw new Error(`Could not connect to ${backendUrl}. If using HTTPS, ensure Mixed Content is allowed, or run the server on HTTPS.`);
        }

        if (!enqueueRes.ok) {
            const txt = await enqueueRes.text();
            throw new Error(`Server Error (${enqueueRes.status}): ${txt}`);
        }
        const { jobId } = await enqueueRes.json();
        console.log(`Job enqueued: ${jobId}. Polling for results...`);

        // Step 2: Poll for Completion
        const maxAttempts = 40; 
        const baseInterval = 1000;

        for (let i = 0; i < maxAttempts; i++) {
            const waitTime = Math.min(5000, baseInterval * Math.pow(1.2, i));
            await new Promise(r => setTimeout(r, waitTime));

            // Also add header here for GET requests
            // Add cache busting param (?t=...) to avoid browser caching stale job states
            const jobRes = await fetch(`${backendUrl}/api/job/${jobId}?t=${Date.now()}`, {
                headers: { 'ngrok-skip-browser-warning': 'true' }
            });

            if (!jobRes.ok) continue; 

            const jobData = await jobRes.json();

            if (jobData.state === 'completed') {
                console.log("Job completed successfully", jobData.result);
                return jobData.result;
            }
            if (jobData.state === 'failed') {
                console.error("Job failed on backend");
                return null;
            }
        }

        throw new Error("Job timed out while waiting for Earth Engine.");

    } catch (error) {
        console.error("GEE Stats Error:", error);
        throw error;
    }
};

