import { fetchSoilData, SoilData } from '../utils/soilService';
import { getBackendUrl, fetchGeeLayer, fetchGeeTimeSeries, GeeTimeSeriesPoint } from '../utils/geeService';
import { ArrowLeft, Wind, Droplets, Sun, Cloud, Layers, RefreshCw, Zap, Loader2, MapPin, Activity, FlaskConical, Database } from 'lucide-react';
