            ) : ndviHistory.length > 0 ? (
                <div className="h-64 w-full">
                     <ResponsiveContainer width="100%" height="100%">
                        <ComposedChart data={ndviHistory}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} />
                            <XAxis 
                                dataKey="date" 
                                tick={{fontSize: 12}} 
                                tickFormatter={(val) => new Date(val).toLocaleDateString(undefined, {month: 'short', day: 'numeric'})}
                            />
                            <YAxis domain={[0, 1]} tick={{fontSize: 12}} />
                            <Tooltip 
                                contentStyle={{borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}}
                                labelStyle={{fontWeight: 'bold', color: '#374151', marginBottom: '0.5rem'}}
                            />
                            <Legend />
                            <Line type="monotone" dataKey="ndvi" stroke="#22c55e" strokeWidth={2} name="NDVI" dot={{r: 2}} activeDot={{r: 5}} />
                            <Line type="monotone" dataKey="ndre" stroke="#eab308" strokeWidth={2} name="NDRE" dot={{r: 2}} />
                            <Line type="monotone" dataKey="ndmi" stroke="#3b82f6" strokeWidth={2} name="NDMI" dot={{r: 2}} />
                        </ComposedChart>
                    </ResponsiveContainer>
                </div>
            ) : (
                <div className="h-64 flex flex-col items-center justify-center text-gray-400">
                    <Database size={32} className="mb-2 opacity-50"/>
                    <p>No historical data available.</p>
                    {isOffline && <p className="text-xs mt-1 text-amber-500">Connect to backend to fetch stats.</p>}
                </div>
            )}
        </div>
    </div>
  );
};
